<div class="space-y-6"><h1 class="text-3xl font-bold">Usuarios administrativos</h1><form method="post" class="grid md:grid-cols-4 gap-3 bg-slate-900 p-4 rounded-xl"><?=$csrf->field()?><input class="bg-slate-800 p-3 rounded" name="name" placeholder="Nombre" required><input class="bg-slate-800 p-3 rounded" name="email" type="email" placeholder="Correo" required><input class="bg-slate-800 p-3 rounded" name="password" type="password" minlength="12" placeholder="Contraseña (12+)" required><button class="bg-cyan-600 rounded">Crear</button></form><div class="overflow-auto border border-slate-800 rounded-xl"><table class="w-full"><thead class="bg-slate-900 text-left text-slate-400"><tr><th class="p-3">ID</th><th>Nombre</th><th>Correo</th><th>Estado</th><th class="p-3 text-right">Control</th></tr></thead><tbody><?php foreach($users as $u):?><tr class="border-t border-slate-800"><td class="p-3"><?=$u['id']?></td><td><?=htmlspecialchars($u['name'])?></td><td><?=htmlspecialchars($u['email'])?></td><td><?=htmlspecialchars($u['status'])?></td><td class="p-3"><div class="flex justify-end"><?php if($u['id']!==\App\Security\Auth::id()):?><form method="post" action="/users/status" onsubmit="return confirm('¿Cambiar el acceso de este usuario administrativo?')"><?=$csrf->field()?><input type="hidden" name="id" value="<?=$u['id']?>"><input type="hidden" name="status" value="<?=$u['status']==='blocked'?'active':'blocked'?>"><button class="<?=$u['status']==='blocked'?'bg-emerald-700':'bg-red-800'?> px-3 py-1 rounded"><?=$u['status']==='blocked'?'Activar':'Ban usuario'?></button></form><?php else:?><span class="text-xs text-slate-500">Sesión actual</span><?php endif?></div></td></tr><?php endforeach?></tbody></table></div></div>
